    "quiz": {
      "questionsEs": [
        {
          "question": "¿Qué importante carrera profesional estudió la brillante Sally Ride?",
          "options": [
            "Medicina de ranas",
            "Física astrofísica e investigación en láseres",
            "Filosofía antigua",
            "Arquitectura naval"
          ],
          "correctIndex": 1,
          "explanation": "Tenía un doctorado de Stanford en física, especializado en astrofísica y rayos láser."
        },
        {
          "question": "¿Qué hito espacial nacional marcó ella a los 32 años?",
          "options": [
            "Caminó en Marte",
            "Piloteó el Concorde sola",
            "Primera mujer estadounidense y más joven del país en espacio",
            "Saltó desde la luna"
          ],
          "correctIndex": 2,
          "explanation": "Se convirtió en la primera mujer astronauta de Estados Unidos y la más joven."
        },
        {
          "question": "¿Cuál era su tarea de mayor complejidad técnica durante el vuelo?",
          "options": [
            "Cocinar comida caliente",
            "Pintar exterior de nave",
            "Operar a precisión la gran grúa gigante del brazo robótico",
            "Limpiar cabina sucia"
          ],
          "correctIndex": 2,
          "explanation": "Fue la experta principal en operar el complejo y largo brazo mecánico (Canadarm)."
        },
        {
          "question": "¿Qué maravilloso programa escolar e interactivo fundó con NASA?",
          "options": [
            "Volar aviones",
            "Lanzar pequeños cohetes",
            "EarthKAM, para que alumnos tomaran fotos reales desde el espacio",
            "Plantar hermosos árboles"
          ],
          "correctIndex": 2,
          "explanation": "EarthKAM permitía a estudiantes secundarios tomar maravillosas fotografías usando satélites orbitales reales."
        },
        {
          "question": "¿Qué meta personal tuvo al escribir asombrosos libros científicos?",
          "options": [
            "Ser millonaria",
            "Aprender español",
            "Inspirar a niñas y niños a amar enormemente las ciencias y matemáticas",
            "Viajar nuevamente a China"
          ],
          "correctIndex": 2,
          "explanation": "Quería eliminar los fuertes prejuicios sociales y emocionar a la niñez con las ciencias exactas."
        }
      ]
    },
